"""hello_fde.py: check that your FDE dev environment is ready.

Run it with:  python hello_fde.py
Exit code is 0 when every required tool is found, 1 otherwise.
"""
import os
import re
import shutil
import subprocess
import sys
from dataclasses import dataclass

VERSION_RE = re.compile(r"(\d+\.\d+(?:\.\d+)?)")


@dataclass
class CheckResult:
    name: str
    ok: bool
    detail: str
    required: bool = True


def parse_version(text):
    """Pull the first version number like 2.43.0 out of a tool's output."""
    match = VERSION_RE.search(text or "")
    return match.group(1) if match else None


def check_python(min_version=(3, 12), version_info=None):
    v = version_info or sys.version_info
    found = f"{v[0]}.{v[1]}.{v[2]}"
    ok = (v[0], v[1]) >= min_version
    need = f"{min_version[0]}.{min_version[1]}+"
    return CheckResult("python", ok, found if ok else f"{found} (need {need})")


def check_tool(name, args=("--version",), required=True,
               which=shutil.which, runner=subprocess.run):
    """Find a command on PATH, run it with --version, and parse the output."""
    path = which(name)
    if path is None:
        return CheckResult(name, False, "not found on PATH", required)
    try:
        out = runner([path, *args], capture_output=True, text=True, timeout=15)
    except (OSError, subprocess.TimeoutExpired) as exc:
        return CheckResult(name, False, f"failed to run: {exc}", required)
    version = parse_version((out.stdout or "") + (out.stderr or ""))
    return CheckResult(name, version is not None, version or "no version in output", required)


def check_venv(prefix=None, base_prefix=None):
    """A virtual environment is active when sys.prefix differs from sys.base_prefix."""
    prefix = prefix or sys.prefix
    base_prefix = base_prefix or sys.base_prefix
    active = prefix != base_prefix
    detail = "active" if active else "not active (run the activate script)"
    return CheckResult("venv", active, detail)


def check_package(module_name):
    try:
        module = __import__(module_name)
    except ImportError:
        return CheckResult(module_name, False, "not installed (pip install -r requirements.txt)")
    return CheckResult(module_name, True, getattr(module, "__version__", "installed"))


def mask(secret):
    """Never print a whole key. Show only a short prefix."""
    return secret[:6] + "..." if len(secret) > 10 else "***"


def check_env_key(key="ANTHROPIC_API_KEY", env=None):
    env = os.environ if env is None else env
    value = env.get(key, "").strip()
    detail = f"set ({mask(value)})" if value else "not set (optional: copy .env.example to .env)"
    return CheckResult(key, bool(value), detail, required=False)


def run_all():
    try:
        from dotenv import load_dotenv
        load_dotenv()  # reads .env in the current folder into os.environ
    except ImportError:
        pass
    return [
        check_python(),
        check_venv(),
        check_tool("git"),
        check_tool("code", required=False),    # VS Code command line launcher
        check_tool("docker", required=False),
        check_package("dotenv"),
        check_env_key(),
    ]


def format_result(r):
    if r.ok:
        tag = "OK  "
    else:
        tag = "FAIL" if r.required else "WARN"
    return f"[{tag}] {r.name:<18} {r.detail}"


def main():
    print("Hello, FDE! Checking your environment...\n")
    results = run_all()
    for r in results:
        print(format_result(r))
    failed = [r.name for r in results if r.required and not r.ok]
    print()
    if failed:
        print("Fix these before moving on: " + ", ".join(failed))
        return 1
    print("All required tools found. You are ready to build.")
    return 0


if __name__ == "__main__":
    sys.exit(main())

"""cleaner.py: validate a messy customer CSV into clean.csv and rejects.csv.

Usage:  python cleaner.py data/customers_messy.csv --out-dir output
"""
import argparse
import csv
import re
import sys
from collections import Counter
from datetime import date, datetime
from pathlib import Path

FIELDS = ["customer_id", "name", "email", "signup_date", "country"]
DATE_FORMATS = ["%Y-%m-%d", "%Y/%m/%d", "%d %b %Y"]  # unambiguous formats only
EMAIL_RE = re.compile(r"^[^@\s]+@[^@\s]+\.[a-z]{2,}$")


class RowError(ValueError):
    """A row problem. kind is a short category used in the summary."""

    def __init__(self, kind, detail=""):
        self.kind = kind
        super().__init__(f"{kind}: {detail}" if detail else kind)


def parse_date(text, today=None):
    today = today or date.today()
    for fmt in DATE_FORMATS:
        try:
            parsed = datetime.strptime(text, fmt).date()
        except ValueError:
            continue
        if parsed > today:
            raise RowError("future date", text)
        return parsed.isoformat()
    raise RowError("bad date", repr(text))


def normalize_email(text):
    email = text.lower()
    if not email:
        raise RowError("missing email")
    if not EMAIL_RE.match(email):
        raise RowError("invalid email", repr(email))
    return email


def clean_row(raw, today=None):
    """Return a cleaned dict, or raise RowError for the first problem found."""
    row = {k: (raw.get(k) or "").strip() for k in FIELDS}
    if not row["customer_id"].isdigit():
        raise RowError("bad id", repr(row["customer_id"]))
    row["customer_id"] = str(int(row["customer_id"]))  # "007" -> "7"
    row["name"] = " ".join(row["name"].split())         # collapse inner spaces
    if not row["name"]:
        raise RowError("missing name")
    row["email"] = normalize_email(row["email"])
    row["signup_date"] = parse_date(row["signup_date"], today)
    country = row["country"].upper()
    if len(country) != 2 or not country.isalpha():
        raise RowError("bad country", repr(row["country"]))
    row["country"] = country
    return row

def clean_rows(rows, today=None):
    """Split rows into (clean, rejects). Duplicates are checked after cleaning."""
    clean, rejects = [], []
    seen_ids, seen_emails = {}, {}
    for line_no, raw in enumerate(rows, start=2):  # line 1 is the header
        try:
            row = clean_row(raw, today)
            if row["customer_id"] in seen_ids:
                raise RowError("duplicate id", f"first seen on line {seen_ids[row['customer_id']]}")
            if row["email"] in seen_emails:
                raise RowError("duplicate email", f"first seen on line {seen_emails[row['email']]}")
        except RowError as err:
            rejects.append({**{k: raw.get(k, "") for k in FIELDS},
                            "line": line_no, "kind": err.kind, "reason": str(err)})
            continue
        seen_ids[row["customer_id"]] = line_no
        seen_emails[row["email"]] = line_no
        clean.append(row)
    return clean, rejects

import sqlite3

import pytest

from load_db import build_db
from run_queries import load_queries, main, run_query

QUERIES = load_queries()


@pytest.fixture
def conn():
    c = build_db()  # fresh in-memory database for every test
    yield c
    c.close()


def rows(conn, name):
    return run_query(conn, QUERIES[name])[1]


def test_all_eight_queries_are_found():
    assert len(QUERIES) == 8
    assert "fanout_bug" in QUERIES and "fanout_fix" in QUERIES


def test_tables_loaded(conn):
    counts = {t: conn.execute(f"SELECT COUNT(*) FROM {t}").fetchone()[0]
              for t in ("customers", "orders", "order_items")}
    assert counts == {"customers": 22, "orders": 12, "order_items": 19}


def test_order_totals_match_items(conn):
    # Data sanity check: the header total equals the sum of its lines.
    mismatches = conn.execute("""
        SELECT o.order_id FROM orders o JOIN order_items i ON i.order_id = o.order_id
        GROUP BY o.order_id HAVING ABS(o.total - SUM(i.qty * i.unit_price)) > 0.001
    """).fetchall()
    assert mismatches == []


def test_customers_per_country(conn):
    result = dict(rows(conn, "customers_per_country"))
    assert result == {"GB": 6, "JP": 5, "US": 4, "DE": 3, "BR": 2, "IN": 2}
    assert sum(result.values()) == 22


def test_revenue_by_customer_keeps_zero_revenue_customers(conn):
    result = rows(conn, "revenue_by_customer")
    assert len(result) == 22
    assert result[0] == (7, "Juno Haddad", 1, 100.0)
    assert sum(r[3] for r in result) == 485.0
    by_id = {r[0]: r for r in result}
    assert by_id[12][3] == 0      # only a pending order
    assert by_id[3][3] == 50.0    # refunded order is excluded


def test_customers_without_orders(conn):
    ids = [r[0] for r in rows(conn, "customers_without_orders")]
    assert len(ids) == 14
    assert 12 not in ids  # a pending order still counts as an order


def test_monthly_running_total(conn):
    assert rows(conn, "monthly_revenue_running") == [
        ("2024-01", 150.0, 150.0), ("2024-02", 10.0, 160.0), ("2024-03", 325.0, 485.0)]


def test_top_customer_per_country(conn):
    assert rows(conn, "top_customer_per_country") == [
        ("GB", "Juno Haddad", 100.0), ("JP", "Dara Li", 55.0), ("US", "Dara Kim", 75.0)]


def test_days_between_orders(conn):
    gaps = {(r[0], r[1]): r[4] for r in rows(conn, "days_between_orders")}
    assert gaps == {(1, 102): 36, (3, 105): 16, (9, 112): 62, (21, 110): 5}


def test_fanout_bug_inflates_and_fix_matches_truth(conn):
    bug = {r[0]: r[2] for r in rows(conn, "fanout_bug")}
    fix = {r[0]: r[2] for r in rows(conn, "fanout_fix")}
    truth = {r[0]: r[3] for r in rows(conn, "revenue_by_customer") if r[3] > 0}
    assert sum(bug.values()) == 835.0   # wrong: totals repeated per item row
    assert fix == truth                 # right: one row per order before joining
    assert bug[7] == fix[7]             # single-item orders hide the bug


def test_units_are_the_same_in_bug_and_fix(conn):
    bug_units = {r[0]: r[3] for r in rows(conn, "fanout_bug")}
    fix_units = {r[0]: r[3] for r in rows(conn, "fanout_fix")}
    assert bug_units == fix_units  # line-level columns are fine; header-level ones are not


def test_foreign_keys_are_enforced(conn):
    with pytest.raises(sqlite3.IntegrityError):
        conn.execute("INSERT INTO orders VALUES (999, 12345, '2024-01-01', 'completed', 1.0)")


def test_runner_prints_named_query(capsys):
    assert main(["fanout_fix"]) == 0
    out = capsys.readouterr().out
    assert "== fanout_fix (7 rows)" in out and "Juno Haddad" in out
